/**
 * COMMUNITY PRESENCE
 * Shows how many teachers are currently online
 * Provides instant comfort and combats teacher isolation
 */

import React, { useState, useEffect } from 'react';
import {
    Box,
    HStack,
    VStack,
    Text,
    useThemedColors,
    Theme,
    LivingGlow,
    SanctuaryCard,
} from '@repo/ui';
import Animated, {
    useAnimatedStyle,
    useSharedValue,
    withRepeat,
    withTiming,
    Easing,
} from 'react-native-reanimated';
import { Users, Info } from 'lucide-react-native';
import { supabase } from '@repo/core';
import { useTranslation } from 'react-i18next';

interface CommunityPresenceProps {
    compact?: boolean;
    userVibe?: string;
    userRole?: 'teacher' | 'student' | 'admin';
}

export default function CommunityPresence({
    compact = false,
    userVibe = 'active',
    userRole = 'teacher'
}: CommunityPresenceProps) {
    const { t } = useTranslation();
    const colors = useThemedColors();
    const [onlineCount, setOnlineCount] = useState<number>(0);
    const [isLoading, setIsLoading] = useState(true);
    const [dominantVibe, setDominantVibe] = useState<string>('active');

    // Pulsing animation for the indicator
    const pulseScale = useSharedValue(1);
    const pulseOpacity = useSharedValue(0.6);

    useEffect(() => {
        pulseScale.value = withRepeat(
            withTiming(1.3, {
                duration: 2500,
                easing: Easing.inOut(Easing.ease),
            }),
            -1,
            true
        );

        pulseOpacity.value = withRepeat(
            withTiming(1, {
                duration: 2500,
                easing: Easing.inOut(Easing.ease),
            }),
            -1,
            true
        );

        fetchOnlineUsers();

        // Specific channel for the user's role to focus the resonance
        const channel = supabase.channel(`online-${userRole}`);

        channel
            .on('presence', { event: 'sync' }, () => {
                const state = channel.presenceState();
                const presences = Object.values(state).flat();
                setOnlineCount(presences.length);

                const vibes: Record<string, number> = {};
                presences.forEach((p: any) => {
                    const v = p.vibe || 'active';
                    vibes[v] = (vibes[v] || 0) + 1;
                });

                const sortedVibes = Object.entries(vibes).sort((a, b) => b[1] - a[1]);
                if (sortedVibes.length > 0) {
                    const topVibe = sortedVibes[0]?.[0];
                    if (topVibe) setDominantVibe(topVibe);
                }
            })
            .on('presence', { event: 'join' }, ({ key, newPresences }) => {
                console.log('User joined sanctuary:', key, newPresences);
            })
            .on('presence', { event: 'leave' }, ({ key, leftPresences }) => {
                console.log('User left sanctuary:', key, leftPresences);
            })
            .subscribe(async (status) => {
                if (status === 'SUBSCRIBED') {
                    await channel.track({
                        vibe: userVibe,
                        role: userRole,
                        online_at: new Date().toISOString(),
                    });
                }
            });

        return () => {
            supabase.removeChannel(channel);
        };
    }, [userVibe, userRole]);

    const fetchOnlineUsers = async () => {
        try {
            // Fallback to DB query for initial count if presence is still syncing
            const fiveMinutesAgo = new Date(Date.now() - 5 * 60 * 1000).toISOString();
            const { count, error } = await supabase
                .from('users')
                .select('id', { count: 'exact', head: true })
                .eq('role', userRole)
                .gte('last_seen_at', fiveMinutesAgo);

            if (!error && count !== null) setOnlineCount(count > 0 ? count : 0);
        } catch (error) {
            console.error('Error fetching online users:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const pulseStyle = useAnimatedStyle(() => ({
        transform: [{ scale: pulseScale.value }],
        opacity: pulseOpacity.value,
    }));

    const getVibeColor = (vibe: string) => {
        switch (vibe) {
            case 'reflecting': return colors.glow;
            case 'teaching': return colors.action;
            case 'studying': return colors.primary;
            case 'planning': return colors.success;
            default: return colors.action;
        }
    };

    const vibeColor = getVibeColor(dominantVibe);
    const roleLabel = userRole === 'teacher' ? t('community.teachers', 'Teachers') : t('community.students', 'Students');

    if (isLoading) {
        return (
            <HStack space="sm" alignItems="center" justifyContent="center" py="$4">
                <Text color={colors.textTertiary} size="sm" italic>
                    {t('community.connecting') || "Joining the Sanctuary Circle..."}
                </Text>
            </HStack>
        );
    }

    if (compact) {
        return (
            <HStack
                space="xs"
                alignItems="center"
                sx={{
                    paddingHorizontal: Theme.spacing.md,
                    paddingVertical: Theme.spacing.sm,
                    backgroundColor: colors.overlay,
                    borderRadius: Theme.corners.comfortable,
                    borderWidth: 1,
                    borderColor: vibeColor,
                }}
            >
                <Animated.View style={pulseStyle}>
                    <Box
                        sx={{
                            width: 8,
                            height: 8,
                            borderRadius: 4,
                            backgroundColor: vibeColor,
                        }}
                    />
                </Animated.View>
                <Text color={colors.textSecondary} size="sm" bold>
                    {onlineCount} {roleLabel} {t('community.online', 'Online')}
                </Text>
            </HStack>
        );
    }

    return (
        <VStack space="md" p={compact ? 0 : "$4"}>
            <HStack space="md" alignItems="center">
                <Box sx={{ position: 'relative' }}>
                    <Users color={vibeColor} size={28} />
                    <Animated.View
                        style={[
                            pulseStyle,
                            {
                                position: 'absolute',
                                top: -2,
                                right: -2,
                                width: 10,
                                height: 10,
                                borderRadius: 5,
                                backgroundColor: vibeColor,
                            },
                        ]}
                    />
                </Box>

                <VStack sx={{ flex: 1 }}>
                    <Text color={colors.text} size="lg" bold>
                        {onlineCount} {roleLabel} in Sanctuary
                    </Text>
                    <Text color={colors.textSecondary} size="sm">
                        {t('community.currently', 'Currently')} {dominantVibe !== 'active' ? t(`community.vibes.${dominantVibe}`, dominantVibe) : t('community.active', 'active')}
                    </Text>
                </VStack>
            </HStack>

            <Box
                sx={{
                    padding: Theme.spacing.md,
                    backgroundColor: colors.overlay,
                    borderRadius: Theme.corners.comfortable,
                    borderLeftWidth: 3,
                    borderLeftColor: vibeColor,
                    marginTop: Theme.spacing.xs
                }}
            >
                <Text color={colors.textPrimary} size="sm" italic>
                    {userRole === 'teacher'
                        ? t('community.comfortMessage', "You are with all other teachers in this journey. The circle is open.")
                        : t('community.studentComfort', "Learning together, growing together. The circle is here for you.")
                    } 🌟
                </Text>
            </Box>
        </VStack>
    );
}

import { SafeZustandStorage, supabase, useStore, GuestDataManager, authAPI } from '@repo/core';
import { useState, useEffect, useCallback } from 'react';

const TIMETABLE_CACHE_KEY = 'gurudevi-timetable-cache';
import { Period } from '../types';

export const useTimetable = (activeDay: number) => {
    const isOnline = useStore(state => state.isOnline);
    const [periods, setPeriods] = useState<Period[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [isAnonymous, setIsAnonymous] = useState(false);


    // Check anonymous status on mount
    useEffect(() => {
        const checkAnonymous = async () => {
            const anon = await authAPI.isAnonymous();
            setIsAnonymous(anon);
        };
        checkAnonymous();
    }, []);

    // Initial load from cache or guest storage
    useEffect(() => {
        const loadCache = async () => {
            try {
                if (isAnonymous) {
                    // Load from guest storage
                    const guestPeriods = await GuestDataManager.getTimetable(activeDay);
                    const mappedPeriods = guestPeriods.map(gp => ({
                        id: gp.localId,
                        user_id: 'guest',
                        day_of_week: gp.day_of_week,
                        period_number: gp.period_number,
                        subject: gp.subject,
                        class_name: gp.class_name,
                        type: gp.type,
                        start_time: gp.start_time,
                        end_time: gp.end_time
                    }));
                    setPeriods(mappedPeriods);
                } else {
                    // Load from regular cache
                    const cached = await SafeZustandStorage.getItem(`${TIMETABLE_CACHE_KEY}-${activeDay}`);
                    if (cached) {
                        setPeriods(JSON.parse(cached));
                    }
                }
            } catch (e) {
                console.warn('Failed to load timetable cache', e);
            } finally {
                setLoading(false);
            }
        };
        loadCache();
    }, [activeDay, isAnonymous]);

    const fetchPeriods = useCallback(async () => {
        // Skip Supabase fetch for anonymous users - they use local storage only
        if (isAnonymous || !isOnline) {
            setLoading(false);
            return;
        }

        // Keep loading true only if we don't have data, otherwise background refresh
        if (periods.length === 0) setLoading(true);

        setError(null);
        try {
            const { data, error } = await supabase
                .from('timetable')
                .select('*')
                .eq('day_of_week', activeDay)
                .order('start_time', { ascending: true });

            if (error) throw error;

            if (data) {
                setPeriods(data);
                // Persist to cache
                SafeZustandStorage.setItem(
                    `${TIMETABLE_CACHE_KEY}-${activeDay}`,
                    JSON.stringify(data)
                );
            }
        } catch (err: any) {
            setError(err.message);
            console.error('Error fetching timetable:', err);
            // Don't throw - just log for authenticated users
        } finally {
            setLoading(false);
        }
    }, [activeDay, isAnonymous, isOnline, periods.length]);

    useEffect(() => {
        fetchPeriods();
    }, [fetchPeriods, isOnline]);

    const addPeriod = async (period: Omit<Period, 'id' | 'user_id'>) => {
        // Optimistic Update
        const tempId = `temp-${Date.now()}`;
        const previousPeriods = [...periods];
        const newPeriodOptimistic = {
            ...period,
            id: tempId,
            user_id: isAnonymous ? 'guest' : 'optimistic'
        } as Period;

        setPeriods(prev => [...prev, newPeriodOptimistic].sort((a, b) => a.start_time.localeCompare(b.start_time)));

        try {
            if (isAnonymous) {
                // Guest mode: Save to local storage
                const guestPeriod = await GuestDataManager.addTimetablePeriod({
                    day_of_week: period.day_of_week,
                    period_number: period.period_number,
                    subject: period.subject,
                    class_name: period.class_name,
                    type: period.type,
                    start_time: period.start_time,
                    end_time: period.end_time
                });

                // Replace temp with real local ID
                setPeriods(prev => prev.map(p => p.id === tempId ? {
                    ...newPeriodOptimistic,
                    id: guestPeriod.localId
                } : p));
            } else {
                // Authenticated mode: Save to Supabase
                const { data: { user } } = await supabase.auth.getUser();
                if (!user) throw new Error("Not authenticated");

                const { data, error } = await supabase
                    .from('timetable')
                    .insert([{ ...period, user_id: user.id }])
                    .select()
                    .single();

                if (error) throw error;

                // Replace temp with real
                setPeriods(prev => prev.map(p => p.id === tempId ? data : p));
            }
        } catch (err: any) {
            // Rollback
            setPeriods(previousPeriods);
            setError(err.message);
            throw err;
        }
    };

    const updatePeriod = async (id: string, updates: Partial<Period>) => {
        const previousPeriods = [...periods];
        setPeriods(prev => prev.map(p => p.id === id ? { ...p, ...updates } : p));

        try {
            if (isAnonymous) {
                // Guest mode: Update local storage
                await GuestDataManager.updateTimetablePeriod(id, updates as any);
            } else {
                // Authenticated mode: Update Supabase
                const { error } = await supabase
                    .from('timetable')
                    .update(updates)
                    .eq('id', id);

                if (error) throw error;
            }
        } catch (err: any) {
            setPeriods(previousPeriods);
            setError(err.message);
            throw err;
        }
    };

    const deletePeriod = async (id: string) => {
        const previousPeriods = [...periods];
        setPeriods(prev => prev.filter(p => p.id !== id));

        try {
            if (isAnonymous) {
                // Guest mode: Delete from local storage
                await GuestDataManager.deleteTimetablePeriod(id);
            } else {
                // Authenticated mode: Delete from Supabase
                const { error } = await supabase
                    .from('timetable')
                    .delete()
                    .eq('id', id);

                if (error) throw error;
            }
        } catch (err: any) {
            setPeriods(previousPeriods);
            setError(err.message);
            throw err;
        }
    };

    return {
        periods,
        loading,
        error,
        fetchPeriods,
        addPeriod,
        updatePeriod,
        deletePeriod
    };
};

/**
 * Types for progressive wellbeing features
 * Aligned with teacher sanctuary philosophy
 */

export interface Goal {
    id: string;
    user_id: string;
    text: string;
    progress: number; // 0-100
    created_at: string;
}

export interface JoyMoment {
    id: string;
    user_id: string;
    student_name?: string;
    moment_description: string;
    category: 'breakthrough' | 'question' | 'connection' | 'other';
    created_at: string;
}

export interface GratitudeEntry {
    id: string;
    user_id: string;
    content: string;
    category: 'student-said' | 'colleague-kindness' | 'personal-win';
    created_at: string;
}

export interface WisdomNote {
    id: string;
    user_id: string;
    insight: string;
    tags?: string[];
    created_at: string;
}

export interface DecisionLog {
    id: string;
    user_id: string;
    decision_text: string;
    context?: string;
    is_reviewed: boolean;
    created_at: string;
}

export interface DailyPrepItem {
    id: string;
    user_id: string;
    item_text: string;
    prep_date: string; // ISO date
    is_completed: boolean;
    created_at: string;
}

export interface UserPreferences {
    id: string;
    user_id: string;
    favorite_features: string[]; // Feature IDs shown on home row
    hidden_features: string[];
    morning_check_time: string; // HH:mm:ss
    afternoon_check_time: string;
    evening_wind_down_time: string;
    enable_contextual_prompts: boolean;
    enable_usage_tracking: boolean;
    updated_at: string;
    created_at: string;
}

export interface FeatureUsageLog {
    id: string;
    user_id: string;
    feature_name: string;
    interaction_type: 'view' | 'interact' | 'complete';
    duration_seconds?: number;
    created_at: string;
}

export interface EnergyForecast {
    id: string;
    user_id: string;
    energy_level: 1 | 2 | 3 | 4 | 5; // 1=depleted, 5=energized
    notes?: string;
    forecast_date: string; // ISO date
    created_at: string;
}

export interface ContextualMoment {
    id: string;
    user_id: string;
    moment_type: 'afternoon_wall' | 'parking_lot_exhale' | 'sunday_prep' | 'morning_energy';
    acknowledged: boolean;
    prompt_text?: string;
    created_at: string;
}

// Feature metadata for progressive disclosure
export interface FeatureMetadata {
    id: string;
    label: string;
    icon: any; // Lucide icon component
    category: 'core' | 'contextual' | 'discover';
    timing?: {
        startTime?: string; // HH:mm
        endTime?: string;
        daysOfWeek?: number[]; // 0-6 (Sunday-Saturday)
    };
    eroi?: number; // Effort Return on Investment ratio
    description: string;
}

export interface MoodLog {
    id: string;
    user_id: string;
    mood_score: number; // 1-5 scale
    mood?: 'joyful' | 'calm' | 'curious' | 'anxious' | 'frustrated' | 'sad';
    note?: string;
    created_at: string;
}

export interface SleepLog {
    id: string;
    user_id: string;
    quality: number; // 1-5 scale
    created_at: string;
}

export interface JournalEntry {
    id: string;
    user_id: string;
    content: string;
    created_at: string;
}

export interface FireJournalEntry {
    id: string;
    user_id: string;
    content_preview: string; // First 50 chars for privacy
    is_burned: boolean;
    created_at: string;
}

export interface Period {
    id: string;
    user_id: string;
    day_of_week: number;
    period_number: number;
    subject: string;
    class_name: string;
    type: 'subject' | 'relief' | 'interval';
    start_time: string;
    end_time: string;
}

export interface DailyContent {
    id: string;
    type: 'motivation' | 'did_you_know';
    content: string;
    author?: string;
    date: string;
    active: boolean;
    created_at: string;
}
